463	    }
464	
465	    /** Give out the sheet's next settle batch number: 1 for the first, then 2, and so on. */
466	    public int nextSettleBatch() {
467	        return ++lastSettleBatch;
468	    }
469	
470	    /** Give out the sheet's next claim number: 1 for the first, then 2, and so on. */
471	    public int nextClaimNumber() {
472	        return ++lastClaimNumber;
473	    }
474	
475	    /** The roles set for an action, comma separated; null when it keeps its standing rule. */
476	    public String getPermission(String action) {
477	        return permissions.get(action);
478	    }
479	
480	    /** Set the roles that may take an action (null: the standing rule). */
481	    public void setPermission(String action, String roles) {
482	        if (roles == null) {
483	            permissions.remove(action);
484	        } else {
485	            permissions.put(action, roles);
486	        }
487	    }
488	
489	    /** Whether a role may take an action: the roles set for it, else its standing rule. */
490	    public boolean permits(String action, String role) {
491	        String roles = permissions.getOrDefault(action, STANDING_PERMISSIONS.get(action));
492	        return Arrays.asList(roles.split(",")).contains(role);
493	    }
494	}
495	package net.officefloor.hq.app.sheet;
496	
497	import java.math.BigDecimal;
498	import java.math.RoundingMode;
499	import java.time.Instant;
500	import net.officefloor.hq.app.Audit;
501	import java.time.LocalDate;
502	import net.officefloor.hq.app.rollup.Rollups;
503	import org.springframework.context.ApplicationEventPublisher;
504	import org.springframework.http.HttpStatus;
505	import org.springframework.web.server.ResponseStatusException;
506	import org.springframework.stereotype.Service;
507	import org.springframework.transaction.annotation.Transactional;
508	
509	/** Loads sheets by id; an id never loaded before starts a new, empty sheet. */
510	@Service
511	public class SheetService {
512	
513	    private final SheetRepository sheets;
514	    private final Rollups rollups;
515	    private final Audit audit;
516	    private final ApplicationEventPublisher events;
517	
518	    public SheetService(SheetRepository sheets, Rollups rollups, Audit audit, ApplicationEventPublisher events) {
519	        this.sheets = sheets;
520	        this.rollups = rollups;
521	        this.audit = audit;
522	        this.events = events;
523	    }
524	
525	    /** Load a sheet; a new sheet's today starts as the real date. */
526	    @Transactional
527	    public synchronized Sheet load(String id) {
528	        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, Instant.now(), LocalDate.now())));
529	    }
530	
531	    /**
532	     * The sheet's today. Every date-dependent decision and every default date on a sheet uses
533	     * this, never the real clock.
534	     */
535	    @Transactional(readOnly = true)
536	    public LocalDate today(String id) {
537	        return load(id).getToday();
538	    }
539	
540	    /**
541	     * Take the sheet's lock, holding it until the caller's transaction ends, so changes that check
542	     * the sheet's other rows before writing are made one at a time.
543	     */
544	    @Transactional
545	    public Sheet lock(String id) {
546	        load(id);
547	        return sheets.findLockedById(id).orElseThrow();
548	    }
549	
550	    /**
551	     * Change the sheet's today, auditing the figures that moves. When it moves, each person's due-total
552	     * as it stood on the day being left is audited first, in list order, and the sheet as it stood at
553	     * the end of that day is kept (see {@link TodayLeaving}). The periods it puts past their grace
554	     * days are closed (see {@link TodayChanged}) before those figures are audited.
555	     */
556	    @Transactional
557	    public synchronized Sheet setToday(String id, String user, LocalDate today) {
558	        Sheet sheet = load(id);
559	        Rollups.Rollup before = rollups.take(id);
560	        if (!today.equals(sheet.getToday())) {
561	            before.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT sheet=" + id + " by=" + user
562	                    + " name=" + figures.name() + " due-total=" + Rollups.shown(figures.dueTotal())));
563	            events.publishEvent(new TodayLeaving(id, sheet.getToday()));
564	        }
565	        sheet.setToday(today);
566	        Sheet saved = sheets.saveAndFlush(sheet);
567	        events.publishEvent(new TodayChanged(id, user, today, saved.getGraceDays()));
568	        rollups.audit(id, user, before);
569	        return saved;
570	    }
571	
572	    /** Whether the sheet is archived: nothing on it may change. */
573	    @Transactional(readOnly = true)
574	    public boolean archived(String id) {
575	        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
576	    }
577	
578	    /** Archive the sheet; refused when it already is. */
579	    @Transactional
580	    public Sheet archive(String id, String user) {
581	        Sheet sheet = lock(id);
582	        if (sheet.isArchived()) {
583	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is already archived.");
584	        }
585	        sheet.setArchived(true);
586	        Sheet saved = sheets.saveAndFlush(sheet);
587	        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
588	        return saved;
589	    }
590	
591	    /** The sheet's clerk limit; null when there is none. */
592	    @Transactional(readOnly = true)
593	    public BigDecimal clerkLimit(String id) {
594	        return load(id).getClerkLimit();
595	    }
596	
597	    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), auditing the change. */
598	    @Transactional
599	    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
600	        return setDated(id, user, Sheet.CLERK_LIMIT, money(limit), from, false);
601	    }
602	
603	    /** Record the sheet's cap (null: no cap) from a date, auditing the change and the figures it moves. */
604	    @Transactional
605	    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
606	        return setDated(id, user, Sheet.CAP, money(cap), from, true);
607	    }
608	
609	    /** Record the sheet's proof threshold (null: none) from a date, auditing the change. */
610	    @Transactional
611	    public Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
612	        return setDated(id, user, Sheet.PROOF_THRESHOLD, money(threshold), from, false);
613	    }
614	
615	    /** Record a grade's proof threshold (null: none, the sheet's applies) from a date, auditing the change. */
616	    @Transactional
617	    public Sheet setGradeProofThreshold(String id, String user, String grade, BigDecimal threshold, LocalDate from) {
618	        return setDated(id, user, Sheet.gradeProofThresholdKey(grade), money(threshold), from, false);
619	    }
620	
621	    /** Record the sheet's note threshold (null: none) from a date, auditing the change. */
622	    @Transactional
623	    public Sheet setNoteThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
624	        return setDated(id, user, Sheet.NOTE_THRESHOLD, money(threshold), from, false);
625	    }
626	
627	    /** Record the sheet's floor from a date, auditing the change and the figures it moves. */
628	    @Transactional
629	    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
630	        return setDated(id, user, Sheet.FLOOR, money(floor), from, true);
631	    }
632	
633	    /** Record the sheet's terms, in days, from a date, auditing the change; claims keep their due-by. */
634	    @Transactional
635	    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
636	        return setDated(id, user, Sheet.TERMS, Integer.toString(terms), from, true);
637	    }
638	
639	    /**
640	     * Record a grade's own terms, in days (null: the sheet's terms), from a date, auditing the change.
641	     * Claims keep their due-by.
642	     */
643	    @Transactional
644	    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
645	        return setDated(id, user, Sheet.gradeTermsKey(grade), terms == null ? null : terms.toString(), from, true);
646	    }
647	
648	    /**
649	     * Record a grade's grace, in days (null: none), from a date, auditing the change and the figures it
650	     * moves. Claims keep their due-by.
651	     */
652	    @Transactional
653	    public Sheet setGradeGrace(String id, String user, String grade, Integer days, LocalDate from) {
654	        return setDated(id, user, Sheet.gradeGraceKey(grade), days == null ? null : days.toString(), from, true);
655	    }
656	
657	    /** Record the sheet's late percent from a date, auditing the change and the figures it moves. */
658	    @Transactional
659	    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
660	        return setDated(id, user, Sheet.LATE_PCT, money(latePct), from, true);
661	    }
662	
663	    /**
664	     * Record a dated setting's value (null: none) from a date, the sheet's today when none is given,
665	     * replacing any value recorded from that date. The change is audited, with the from-date when one
666	     * was given, and so are the figures it moves when it can move any.
667	     */
668	    private Sheet setDated(String id, String user, String key, String value, LocalDate from, boolean movesFigures) {
669	        Sheet sheet = lock(id);
670	        Rollups.Rollup before = movesFigures ? rollups.take(id) : null;
671	        sheet.record(key, from == null ? sheet.getToday() : from, value);
672	        Sheet saved = sheets.saveAndFlush(sheet);
673	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value="
674	                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
675	        if (movesFigures) {
676	            rollups.audit(id, user, before);
677	        }
678	        return saved;
679	    }
680	
681	    /** A figure with two decimals as text; null stays null. */
682	    private static String money(BigDecimal value) {
683	        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
684	    }
685	
686	    /** Change the sheet's policy date (null: the sheet's today), auditing the change and the figures it moves. */
687	    @Transactional
688	    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
689	        Sheet sheet = lock(id);
690	        Rollups.Rollup before = rollups.take(id);
691	        sheet.setPolicyDate(policyDate);
692	        Sheet saved = sheets.saveAndFlush(sheet);
693	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
694	                + (saved.getPolicyDate() == null ? "" : saved.getPolicyDate().toString()));
695	        rollups.audit(id, user, before);
696	        return saved;
697	    }
698	
699	    /** Change the sheet's period-numbering-from date (null: off), auditing the change. */
700	    @Transactional
701	    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
702	        Sheet sheet = lock(id);
703	        sheet.setPeriodNumberingFrom(from);
704	        Sheet saved = sheets.saveAndFlush(sheet);
705	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
706	                + (saved.getPeriodNumberingFrom() == null ? "" : saved.getPeriodNumberingFrom().toString()));
707	        return saved;
708	    }
709	
710	    /** Change the sheet's entry date (null: off), auditing the change. */
711	    @Transactional
712	    public Sheet setEntryDate(String id, String user, LocalDate entryDate) {
713	        Sheet sheet = lock(id);
714	        sheet.setEntryDate(entryDate);
715	        Sheet saved = sheets.saveAndFlush(sheet);
716	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=entry-date value="
717	                + (saved.getEntryDate() == null ? "" : saved.getEntryDate().toString()));
718	        return saved;
719	    }
720	
721	    /** Change the sheet's grace days (null: off), auditing the change. */
722	    @Transactional
723	    public Sheet setGraceDays(String id, String user, Integer graceDays) {
724	        Sheet sheet = lock(id);
725	        sheet.setGraceDays(graceDays);
726	        Sheet saved = sheets.saveAndFlush(sheet);
727	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=grace-days value="
728	                + (saved.getGraceDays() == null ? "" : saved.getGraceDays().toString()));
729	        return saved;
730	    }
731	
732	    /** Set the roles that may take an action (null: the standing rule), auditing the change. */
733	    @Transactional
