374	  constructor() {
375	    // Every sheet load re-reads the sheet's settings and roles from the store.
376	    effect(() => {
377	      const sheet = this.session.sheet();
378	      const loads = this.session.loads();
379	      untracked(() => {
380	        this.clerkLimit.set(null);
381	        this.proofThreshold.set(null);
382	        this.noteThreshold.set(null);
383	        this.gradeTerms.set({ A: null, B: null, C: null });
384	        this.gradeGrace.set({ A: null, B: null, C: null });
385	        this.gradeProofThreshold.set({ A: null, B: null, C: null });
386	        this.periodNumberingFrom.set('');
387	        this.entryDate.set('');
388	        this.graceDays.set('');
389	        this.permissions.set(Settings.noPermissions());
390	        this.roles.set([]);
391	        this.fromInput.set(Settings.noFroms());
392	        this.settingsError.set(null);
393	        this.roleError.set(null);
394	        if (sheet) void this.reload(sheet, loads);
395	      });
396	    });
397	    // A change to the sheet's today changes which dated values are in force.
398	    let shownToday: string | null = null;
399	    effect(() => {
400	      const today = this.session.today();
401	      untracked(() => {
402	        const sheet = this.session.sheet();
403	        const changed = shownToday !== null && today !== shownToday;
404	        shownToday = today;
405	        if (sheet && changed) void this.todayChanged(sheet);
406	      });
407	    });
408	  }
