411	  protected fromTyped(key: DatedKey, value: string): void {
412	    this.fromInput.update((all) => ({ ...all, [key]: value }));
413	    if (key === 'clerk-limit') this.limitEdited = true;
414	    else if (key === 'cap') this.capEdited = true;
415	    else if (key === 'proof-threshold') this.proofThresholdEdited = true;
416	    else if (key === 'note-threshold') this.noteThresholdEdited = true;
417	    else if (key === 'floor') this.floorEdited = true;
418	    else if (key === 'terms') this.termsEdited = true;
419	    else if (key === 'late-pct') this.latePctEdited = true;
420	    else if (key.startsWith('proof-threshold-')) this.gradeProofThresholdEdited.add(key.slice('proof-threshold-'.length) as Grade);
421	    else if (key.startsWith('grace-')) this.gradeGraceEdited.add(key.slice('grace-'.length) as Grade);
422	    else this.gradeTermsEdited.add(key.slice('terms-'.length) as Grade);
423	    this.settingsError.set(null);
424	  }
