497	  protected async saveSettings(event: Event): Promise<void> {
498	    event.preventDefault();
499	    this.settingsError.set(null);
500	    const sheet = this.session.sheet();
501	    if (!sheet) return;
502	    const limit = this.limit().trim();
503	    const cap = this.capInput().trim();
504	    const floor = this.floorInput().trim();
505	    const proofThreshold = this.proofThresholdInput().trim();
506	    const noteThreshold = this.noteThresholdInput().trim();
507	    // With nothing typed since the last save, saving sets the clerk limit again as it stands.
508	    const terms = this.termsInput().trim();
509	    const latePct = this.latePctInput().trim();
510	    const policyDate = this.policyDateInput().trim();
511	    const periodNumberingFrom = this.periodNumberingFromInput().trim();
512	    const entryDate = this.entryDateInput().trim();
513	    const graceDays = this.graceDaysInput().trim();
514	    const saveLimit =
515	      this.limitEdited ||
516	      (!this.capEdited && !this.proofThresholdEdited && !this.noteThresholdEdited && !this.floorEdited && !this.termsEdited && this.gradeTermsEdited.size === 0 && this.gradeGraceEdited.size === 0 && this.gradeProofThresholdEdited.size === 0 && !this.latePctEdited && !this.policyDateEdited &&
517	        !this.periodNumberingFromEdited && !this.entryDateEdited && !this.graceDaysEdited && this.permissionsEdited.size === 0);
518	    const saveCap = this.capEdited;
519	    const saveProofThreshold = this.proofThresholdEdited;
520	    const saveNoteThreshold = this.noteThresholdEdited;
521	    const saveFloor = this.floorEdited;
522	    const saveTerms = this.termsEdited;
523	    const saveGradeTerms = GRADES.filter((g) => this.gradeTermsEdited.has(g))
524	      .map((g) => ({ grade: g, value: this.gradeTermsInput()[g].trim() }));
525	    const saveGradeGrace = GRADES.filter((g) => this.gradeGraceEdited.has(g))
526	      .map((g) => ({ grade: g, value: this.gradeGraceInput()[g].trim() }));
527	    const saveGradeProofThresholds = GRADES.filter((g) => this.gradeProofThresholdEdited.has(g))
528	      .map((g) => ({ grade: g, value: this.gradeProofThresholdInput()[g].trim() }));
529	    const saveLatePct = this.latePctEdited;
530	    const savePolicyDate = this.policyDateEdited;
531	    const savePeriodNumberingFrom = this.periodNumberingFromEdited;
532	    const saveEntryDate = this.entryDateEdited;
533	    const saveGraceDays = this.graceDaysEdited;
534	    const savePermissions = PERMISSION_ACTIONS.filter((a) => this.permissionsEdited.has(a))
535	      .map((a) => ({ action: a, value: this.permissionInput()[a].trim() }));
536	    const froms = this.fromInput();
537	    const from = (key: DatedKey) => froms[key].trim();
538	    const savedKeys: DatedKey[] = [
539	      ...(saveLimit ? (['clerk-limit'] as const) : []),
540	      ...(saveCap ? (['cap'] as const) : []),
541	      ...(saveProofThreshold ? (['proof-threshold'] as const) : []),
542	      ...saveGradeProofThresholds.map((t) => this.proofKey(t.grade)),
543	      ...(saveNoteThreshold ? (['note-threshold'] as const) : []),
544	      ...(saveFloor ? (['floor'] as const) : []),
545	      ...(saveTerms ? (['terms'] as const) : []),
546	      ...saveGradeTerms.map((t) => this.gradeKey(t.grade)),
547	      ...saveGradeGrace.map((t) => this.graceKey(t.grade)),
548	      ...(saveLatePct ? (['late-pct'] as const) : []),
549	    ];
550	    if (savedKeys.some((key) => !SETTING_FROM.test(from(key)))) {
551	      this.settingsError.set('Type a from-date as yyyy-mm-dd, or leave it empty for the sheet\'s today.');
552	      return;
553	    }
554	    if (saveLimit && !LIMIT.test(limit)) {
555	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it empty for no limit.');
556	      return;
557	    }
558	    if (saveCap && !CAP.test(cap)) {
559	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it empty for no cap.');
560	      return;
561	    }
562	    if (saveProofThreshold && !PROOF_THRESHOLD.test(proofThreshold)) {
563	      this.settingsError.set('Type a proof threshold of 0.00 or more, with up to two decimals, or leave it empty for none.');
564	      return;
565	    }
566	    if (saveGradeProofThresholds.some((t) => !PROOF_THRESHOLD.test(t.value))) {
567	      this.settingsError.set('Type a grade\'s proof threshold of 0.00 or more, with up to two decimals, or leave it empty for the sheet\'s.');
568	      return;
569	    }
570	    if (saveNoteThreshold && !NOTE_THRESHOLD.test(noteThreshold)) {
571	      this.settingsError.set('Type a note threshold of 0.00 or more, with up to two decimals, or leave it empty for none.');
572	      return;
573	    }
574	    if (saveFloor && !FLOOR.test(floor)) {
575	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
576	      return;
577	    }
578	    if (saveTerms && !TERMS.test(terms)) {
579	      this.settingsError.set('Type terms as a whole number of days.');
580	      return;
581	    }
582	    if (saveGradeTerms.some((t) => !GRADE_TERMS.test(t.value))) {
583	      this.settingsError.set('Type a grade\'s terms as a whole number of days, or leave them empty for the sheet\'s terms.');
584	      return;
585	    }
586	    if (saveGradeGrace.some((t) => !GRADE_GRACE.test(t.value))) {
587	      this.settingsError.set('Type a grade\'s grace as a whole number of days, or leave it empty for none.');
588	      return;
589	    }
590	    if (saveLatePct && !LATE_PCT.test(latePct)) {
591	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
592	      return;
593	    }
594	    if (savePolicyDate && !POLICY_DATE.test(policyDate)) {
595	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it empty for the sheet\'s today.');
596	      return;
597	    }
598	    if (savePeriodNumberingFrom && !PERIOD_NUMBERING_FROM.test(periodNumberingFrom)) {
599	      this.settingsError.set('Type the date period numbering is from as yyyy-mm-dd, or leave it empty for off.');
600	      return;
601	    }
602	    if (saveEntryDate && !ENTRY_DATE.test(entryDate)) {
603	      this.settingsError.set('Type an entry date as yyyy-mm-dd, or leave it empty for off.');
604	      return;
605	    }
606	    if (saveGraceDays && !GRACE_DAYS.test(graceDays)) {
607	      this.settingsError.set('Type grace days as a whole number of days, or leave them empty for off.');
608	      return;
609	    }
610	    if (savePermissions.some((p) => !PERMISSION.test(p.value))) {
611	      this.settingsError.set('Type the roles that may take an action as clerk or steward, comma separated, or leave them empty for the standing rule.');
612	      return;
613	    }
614	    // What was typed is taken now: anything typed meanwhile is saved by the next submit.
615	    if (saveLimit) this.limitEdited = false;
616	    if (saveCap) this.capEdited = false;
617	    if (saveProofThreshold) this.proofThresholdEdited = false;
618	    for (const t of saveGradeProofThresholds) this.gradeProofThresholdEdited.delete(t.grade);
619	    if (saveNoteThreshold) this.noteThresholdEdited = false;
620	    if (saveFloor) this.floorEdited = false;
621	    if (saveTerms) this.termsEdited = false;
622	    for (const t of saveGradeTerms) this.gradeTermsEdited.delete(t.grade);
623	    for (const t of saveGradeGrace) this.gradeGraceEdited.delete(t.grade);
624	    if (saveLatePct) this.latePctEdited = false;
625	    if (savePolicyDate) this.policyDateEdited = false;
626	    if (savePeriodNumberingFrom) this.periodNumberingFromEdited = false;
627	    if (saveEntryDate) this.entryDateEdited = false;
628	    if (saveGraceDays) this.graceDaysEdited = false;
629	    for (const p of savePermissions) this.permissionsEdited.delete(p.action);
630	    this.fromInput.update((all) => {
631	      const next = { ...all };
632	      for (const key of savedKeys) next[key] = '';
633	      return next;
634	    });
635	    const write = async () => {
636	      try {
637	        if (saveLimit) {
638	          this.inForce(await this.api.setClerkLimit(sheet, limit, from('clerk-limit')));
639	        }
640	        if (saveCap) {
641	          const view = await this.api.setCap(sheet, cap, from('cap'));
642	          this.inForce(view);
643	          if (!this.capEdited) this.capInput.set(view.cap ?? '');
644	        }
645	        if (saveProofThreshold) {
646	          const view = await this.api.setProofThreshold(sheet, proofThreshold, from('proof-threshold'));
647	          this.inForce(view);
648	          if (!this.proofThresholdEdited) this.proofThresholdInput.set(view.proofThreshold ?? '');
649	        }
650	        for (const t of saveGradeProofThresholds) {
651	          this.inForce(await this.api.setGradeProofThreshold(sheet, t.grade, t.value, from(this.proofKey(t.grade))));
652	        }
653	        if (saveNoteThreshold) {
654	          const view = await this.api.setNoteThreshold(sheet, noteThreshold, from('note-threshold'));
655	          this.inForce(view);
656	          if (!this.noteThresholdEdited) this.noteThresholdInput.set(view.noteThreshold ?? '');
657	        }
658	        if (saveFloor) {
659	          this.inForce(await this.api.setFloor(sheet, floor, from('floor')));
660	        }
661	        if (saveTerms) {
662	          this.inForce(await this.api.setTerms(sheet, terms, from('terms')));
663	        }
664	        for (const t of saveGradeTerms) {
665	          this.inForce(await this.api.setGradeTerms(sheet, t.grade, t.value, from(this.gradeKey(t.grade))));
666	        }
667	        for (const t of saveGradeGrace) {
668	          this.inForce(await this.api.setGradeGrace(sheet, t.grade, t.value, from(this.graceKey(t.grade))));
669	        }
670	        if (saveLatePct) {
671	          this.inForce(await this.api.setLatePct(sheet, latePct, from('late-pct')));
672	        }
673	        if (savePolicyDate) {
674	          const view = await this.api.setPolicyDate(sheet, policyDate);
675	          this.session.policyDate.set(view.policyDate ?? '');
676	          if (!this.policyDateEdited) this.policyDateInput.set(view.policyDate ?? '');
677	        }
678	        if (savePeriodNumberingFrom) {
679	          const view = await this.api.setPeriodNumberingFrom(sheet, periodNumberingFrom);
680	          this.periodNumberingFrom.set(view.periodNumberingFrom ?? '');
681	          if (!this.periodNumberingFromEdited) this.periodNumberingFromInput.set(view.periodNumberingFrom ?? '');
682	        }
683	        if (saveEntryDate) {
684	          const view = await this.api.setEntryDate(sheet, entryDate);
685	          this.entryDate.set(view.entryDate ?? '');
686	          if (!this.entryDateEdited) this.entryDateInput.set(view.entryDate ?? '');
687	        }
688	        if (saveGraceDays) {
689	          const view = await this.api.setGraceDays(sheet, graceDays);
690	          this.graceDays.set(view.graceDays?.toString() ?? '');
691	          if (!this.graceDaysEdited) this.graceDaysInput.set(view.graceDays?.toString() ?? '');
692	        }
693	        for (const p of savePermissions) {
694	          const view = await this.api.setPermission(sheet, p.action, p.value);
695	          this.permissions.set(view.permissions);
696	          if (!this.permissionsEdited.has(p.action)) {
697	            this.permissionInput.update((all) => ({ ...all, [p.action]: view.permissions[p.action] }));
698	          }
699	        }
700	      } catch {
701	        this.settingsError.set('The settings could not be saved.');
702	      }
703	    };
704	    this.saving = this.saving.then(write);
705	    await this.saving;
706	  }
