708	  protected async saveRole(event: Event): Promise<void> {
709	    event.preventDefault();
710	    if (this.busy) return;
711	    this.roleError.set(null);
712	    const sheet = this.session.sheet();
713	    if (!sheet) return;
714	    const user = this.roleUser().trim();
715	    const role = this.roleName().trim();
716	    if (!user) {
717	      this.roleError.set('Type the user name to set a role for.');
718	      return;
719	    }
720	    if (!(ROLES as readonly string[]).includes(role)) {
721	      this.roleError.set(`A role is ${this.roleNames}.`);
722	      return;
723	    }
724	    this.busy = true;
725	    try {
726	      const saved = await this.api.setRole(sheet, { user, role: role as RoleName });
727	      this.roles.update((all) =>
728	        [...all.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
729	      );
730	      this.roleUser.set('');
731	      this.roleName.set('');
732	    } catch {
733	      this.roleError.set(`The role of ${user} could not be set.`);
734	    } finally {
735	      this.busy = false;
736	    }
737	  }
