762	  private async reload(sheet: string, loads: number): Promise<void> {
763	    const [settings, roles] = await Promise.all([this.api.get(sheet), this.api.roles(sheet)]);
764	    // A later load may have started while this one was in flight: only the latest is shown.
765	    if (this.session.sheet() === sheet && this.session.loads() === loads) {
766	      this.inForce(settings);
767	      // The cap's input starts at the cap in force, so clearing it is a change.
768	      this.capInput.set(settings.cap ?? '');
769	      this.capEdited = false;
770	      // So does the proof threshold's.
771	      this.proofThresholdInput.set(settings.proofThreshold ?? '');
772	      this.proofThresholdEdited = false;
773	      // And the note threshold's.
774	      this.noteThresholdInput.set(settings.noteThreshold ?? '');
775	      this.noteThresholdEdited = false;
776	      this.session.policyDate.set(settings.policyDate ?? '');
777	      // The policy date's input starts at the date in force, so clearing it is a change.
778	      this.policyDateInput.set(settings.policyDate ?? '');
779	      this.policyDateEdited = false;
780	      // Period numbering from starts at the date in force too, so clearing it is a change.
781	      this.periodNumberingFrom.set(settings.periodNumberingFrom ?? '');
782	      this.periodNumberingFromInput.set(settings.periodNumberingFrom ?? '');
783	      this.periodNumberingFromEdited = false;
784	      // The entry date starts at the date in force too, so clearing it is a change.
785	      this.entryDate.set(settings.entryDate ?? '');
786	      this.entryDateInput.set(settings.entryDate ?? '');
787	      this.entryDateEdited = false;
788	      // Grace days start at those in force, so clearing them is a change.
789	      this.graceDays.set(settings.graceDays?.toString() ?? '');
790	      this.graceDaysInput.set(settings.graceDays?.toString() ?? '');
791	      this.graceDaysEdited = false;
792	      // Each action's roles start at those in force, so clearing them is a change.
793	      this.permissions.set(settings.permissions);
794	      this.permissionInput.set({ ...settings.permissions });
795	      this.permissionsEdited.clear();
